$ErrorActionPreference = 'Stop'
$env:AWS_PAGER = ''

# Generated by RoleCraft — https://rolecraft.omhinge.cloud
# Creates an IAM role with its trust policy and permissions.

$RoleName = 'lambda-api'

# Trust policy: who can assume the role
[System.IO.File]::WriteAllText((Join-Path $PWD 'trust.json'), @'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "lambda.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
'@)

# Permissions policy
[System.IO.File]::WriteAllText((Join-Path $PWD 'policy.json'), @'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "LambdaInvokeFunction",
      "Effect": "Allow",
      "Action": "lambda:InvokeFunction",
      "Resource": [
        "arn:aws:lambda:*:*:function:orders-api",
        "arn:aws:lambda:*:*:function:orders-api:*"
      ]
    },
    {
      "Sid": "DynamodbReadWriteTable",
      "Effect": "Allow",
      "Action": [
        "dynamodb:BatchGetItem",
        "dynamodb:BatchWriteItem",
        "dynamodb:ConditionCheckItem",
        "dynamodb:DeleteItem",
        "dynamodb:DescribeTable",
        "dynamodb:GetItem",
        "dynamodb:PutItem",
        "dynamodb:Query",
        "dynamodb:Scan",
        "dynamodb:UpdateItem"
      ],
      "Resource": "arn:aws:dynamodb:*:*:table/orders"
    },
    {
      "Sid": "DynamodbReadWriteIndex",
      "Effect": "Allow",
      "Action": [
        "dynamodb:Query",
        "dynamodb:Scan"
      ],
      "Resource": "arn:aws:dynamodb:*:*:table/orders/index/*"
    },
    {
      "Sid": "LogsWriteGroup",
      "Effect": "Allow",
      "Action": [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ],
      "Resource": "arn:aws:logs:*:*:log-group:/aws/lambda/orders-api:*"
    }
  ]
}
'@)

aws iam create-role --role-name $RoleName --assume-role-policy-document file://trust.json --description 'Created with RoleCraft' | Out-Null
if ($LASTEXITCODE -ne 0) { throw "aws failed: create-role" }
aws iam put-role-policy --role-name $RoleName --policy-name "${RoleName}-inline" --policy-document file://policy.json
if ($LASTEXITCODE -ne 0) { throw "aws failed: put-role-policy" }

Write-Host "Created role $RoleName."
Write-Host "Added inline policy ${RoleName}-inline."
